package com.opensocket.aievent.core.iam.authentication.domain;
import java.time.Instant;import java.util.Objects;import java.util.Optional;
public final class SubjectSecurityState{private final CredentialSubjectType subjectType;private final String subjectId;private final int failedLoginCount;private final Optional<Instant> lockedUntil;private final Optional<Instant> lastSuccessAt;private final long version;private SubjectSecurityState(CredentialSubjectType type,String id,int failed,Optional<Instant> locked,Optional<Instant> success,long version){subjectType=Objects.requireNonNull(type,"subjectType");subjectId=Text.required(id,"subjectId",128);if(failed<0)throw new IllegalArgumentException("failedLoginCount must be non-negative");failedLoginCount=failed;lockedUntil=locked==null?Optional.empty():locked;lastSuccessAt=success==null?Optional.empty():success;if(version<1)throw new IllegalArgumentException("version must be positive");this.version=version;}public static SubjectSecurityState initial(CredentialSubjectType type,String id){return new SubjectSecurityState(type,id,0,Optional.empty(),Optional.empty(),1);}public static SubjectSecurityState reconstitute(CredentialSubjectType type,String id,int failed,Optional<Instant> locked,Optional<Instant> success,long version){return new SubjectSecurityState(type,id,failed,locked,success,version);}public SubjectSecurityState recordFailure(Instant at,PasswordPolicy policy){int next=failedLoginCount+1;Optional<Instant> lock=next>=policy.failedAttemptThreshold()?Optional.of(at.plus(policy.lockoutDuration())):lockedUntil;return new SubjectSecurityState(subjectType,subjectId,next,lock,lastSuccessAt,version+1);}public SubjectSecurityState recordSuccess(Instant at){return new SubjectSecurityState(subjectType,subjectId,0,Optional.empty(),Optional.of(at),version+1);}public boolean lockedAt(Instant at){return lockedUntil.map(t->at.isBefore(t)).orElse(false);}public CredentialSubjectType subjectType(){return subjectType;}public String subjectId(){return subjectId;}public int failedLoginCount(){return failedLoginCount;}public Optional<Instant> lockedUntil(){return lockedUntil;}public Optional<Instant> lastSuccessAt(){return lastSuccessAt;}public long version(){return version;}}
